      const nw = b3.neckW / 2 + 0.8, pinY = -T16 + 0.3 * T16, tipY = -T16 + (child ? 0.52 : 0.66) * T16, cin = Math.max(chestIn(b3), 4 * k8);
      const fl4 = (child ? 1.4 : 2) * k8, step2 = 1.5 * k8, fw = 0.62 * k8;
